#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Fast edge lookup using sorted adjacency lists
    for(int i = 1; i <= n; i++){
        sort(adj[i].begin(), adj[i].end());
        sort(radj[i].begin(), radj[i].end());
    }

    auto has_edge = [&](int u, int v) -> bool {
        return binary_search(adj[u].begin(), adj[u].end(), v);
    };

    auto now_f = chrono::steady_clock::now;
    auto start_time = now_f();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now_f()-start_time).count();};

    // DAG check + longest path
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){
                        dp[u] = dp[v] + 1;
                        nxt[u] = v;
                    }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){
                if(i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // Greedy path builder with Warnsdorff + randomized restarts
    auto build_and_improve = [&]() {
        int sv = rng() % n + 1;
        vector<bool> used(n+1, false);
        deque<int> path;
        path.push_back(sv);
        used[sv] = true;

        // Extend back
        while(true){
            int c = path.back();
            int best = -1, best_score = INT_MAX;
            int cnt = 0;
            for(int v : adj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : adj[v]) if(!used[w]) s++;
                if(s < best_score){
                    best_score = s; best = v; cnt = 1;
                } else if(s == best_score){
                    cnt++;
                    if(rng() % cnt == 0) best = v;
                }
            }
            if(best == -1) break;
            used[best] = true;
            path.push_back(best);
        }

        // Extend front
        while(true){
            int c = path.front();
            int best = -1, best_score = INT_MAX;
            int cnt = 0;
            for(int v : radj[c]){
                if(used[v]) continue;
                int s = 0;
                for(int w : radj[v]) if(!used[w]) s++;
                if(s < best_score){
                    best_score = s; best = v; cnt = 1;
                } else if(s == best_score){
                    cnt++;
                    if(rng() % cnt == 0) best = v;
                }
            }
            if(best == -1) break;
            used[best] = true;
            path.push_front(best);
        }

        // Convert to vector for insertion
        vector<int> vpath(path.begin(), path.end());

        // Repeated vertex insertion passes
        for(int pass = 0; pass < 3; pass++){
            bool any = false;
            for(int v = 1; v <= n; v++){
                if(used[v]) continue;
                // Try front
                if(has_edge(v, vpath[0])){
                    vpath.insert(vpath.begin(), v);
                    used[v] = true; any = true; continue;
                }
                // Try back
                if(has_edge(vpath.back(), v)){
                    vpath.push_back(v);
                    used[v] = true; any = true; continue;
                }
                // Try middle
                for(int i = 0; i + 1 < (int)vpath.size(); i++){
                    if(has_edge(vpath[i], v) && has_edge(v, vpath[i+1])){
                        vpath.insert(vpath.begin()+i+1, v);
                        used[v] = true; any = true; break;
                    }
                }
            }
            if(!any) break;
        }

        if((int)vpath.size() > (int)best_path.size()) best_path = vpath;
    };

    while(elapsed_ms() < 3800 && (int)best_path.size() < n){
        build_and_improve();
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
    return 0;
}
